async function syncProgress(){if(!supabaseClient||!authUser)return;try{const {error}=await supabaseClient.from('player_progress').upsert({user_id:authUser.id,progress:progress,updated_at:new Date().toISOString()},{onConflict:'user_id'});if(error)throw error;document.getElementById('syncStatus').textContent='SUPABASE SESSION / progress synchronized';}catch(e){document.getElementById('syncStatus').textContent='SUPABASE SESSION / sync unavailable — local progress remains saved';console.warn(e.message)}}
async function initCloud(){const status=document.getElementById('syncStatus');if(!supabaseClient){status.textContent='LOCAL SESSION / Supabase library unavailable; local progress enabled';return;}try{let {data:{session}}=await supabaseClient.auth.getSession();if(!session){const {data,error}=await supabaseClient.auth.signInAnonymously();if(error)throw error;session=data.session;}authSession=session;authUser=session.user;supabaseClient.auth.onAuthStateChange((_event, nextSession)=>{authSession=nextSession;authUser=nextSession?.user||null;});const {data,error}=await supabaseClient.from('player_progress').select('progress').eq('user_id',authUser.id).maybeSingle();if(error)throw error;if(data&&data.progress){const cloud=data.progress;progress.solved=[...new Set([...(progress.solved||[]),...(cloud.solved||[])])].sort();progress.hints={...cloud.hints,...progress.hints};progress.stage3Solved=[...new Set([...(progress.stage3Solved||[]),...(cloud.stage3Solved||[])])].sort();progress.stage3Hints={...(cloud.stage3Hints||{}),...(progress.stage3Hints||{})};progress.stage4Solved=[...new Set([...(progress.stage4Solved||[]),...(cloud.stage4Solved||[])])].sort();progress.stage4Hints={...(cloud.stage4Hints||{}),...(progress.stage4Hints||{})};progress.stage5Solved=[...new Set([...(progress.stage5Solved||[]),...(cloud.stage5Solved||[])])].sort();progress.stage5Hints={...(cloud.stage5Hints||{}),...(progress.stage5Hints||{})};progress.stage6Solved=[...new Set([...(progress.stage6Solved||[]),...(cloud.stage6Solved||[])])].sort();progress.stage6Hints={...(cloud.stage6Hints||{}),...(progress.stage6Hints||{})};progress.stage7Solved=[...new Set([...(progress.stage7Solved||[]),...(cloud.stage7Solved||[])])].sort();progress.stage7Hints={...(cloud.stage7Hints||{}),...(progress.stage7Hints||{})};progress.stage8Solved=[...new Set([...(progress.stage8Solved||[]),...(cloud.stage8Solved||[])])].sort();progress.stage8Hints={...(cloud.stage8Hints||{}),...(progress.stage8Hints||{})};progress.stage9Solved=[...new Set([...(progress.stage9Solved||[]),...(cloud.stage9Solved||[])])].sort();progress.stage9Hints={...(cloud.stage9Hints||{}),...(progress.stage9Hints||{})};progress.stage10Solved=[...new Set([...(progress.stage10Solved||[]),...(cloud.stage10Solved||[])])].sort();progress.stage10Hints={...(cloud.stage10Hints||{}),...(progress.stage10Hints||{})};progress.ending=progress.ending||cloud.ending||null;}status.textContent='SUPABASE SESSION / anonymous player recognized';saveLocal();}catch(e){status.textContent='LOCAL SESSION / Supabase setup pending; local progress enabled';console.warn('Cloud sync not ready:',e.message)}}
