function termPathUnlocked(path){const p=path.toLowerCase();if(p.startsWith('/forgotten/')||p==='/forgotten/')return progress.stage3Solved.length===3;if(p.startsWith('/root/')||p==='/root/')return progress.stage3Solved.length===3;if(p.startsWith('/afterword/')||p==='/afterword/')return !!progress.ending;if(p.startsWith('/unwritten/')||p==='/unwritten/')return progress.stage4Solved.length===3;if(p.startsWith('/living-index/')||p==='/living-index/')return progress.stage5Solved.length===3;if(p.startsWith('/seventh-seal/')||p==='/seventh-seal/')return progress.stage6Solved.length===3;if(p.startsWith('/eighth-witness/')||p==='/eighth-witness/')return progress.stage7Solved.length===3;if(p.startsWith('/last-keeper/')||p==='/last-keeper/')return progress.stage8Solved.length===3;if(p.startsWith('/end-of-archive/')||p==='/end-of-archive/')return progress.stage9Solved.length===3;return true;}
function termResolve(path){if(!path||path==='.')return termCwd;if(path==='~')return '/';let p=path.startsWith('/')?path:termCwd+path;let parts=[];for(const bit of p.split('/')){if(!bit||bit==='.')continue;if(bit==='..')parts.pop();else parts.push(bit);}return '/'+parts.join('/')+(p.endsWith('/')&&parts.length?'/':'');}
