  const pageDialog=document.getElementById('notebookPageDialog'),dialogInput=document.getElementById('notebookDialogInput'),dialogTitle=document.getElementById('notebookDialogTitle'),dialogMessage=document.getElementById('notebookDialogMessage'),dialogConfirm=document.getElementById('notebookDialogConfirm');
