 const maintenancePage=document.getElementById('maintenance');maintenancePage?.querySelectorAll('.doc').forEach(el=>{el.classList.add('evidence-target');el.addEventListener('click',()=>{if(el.innerText.includes('2017-09-11'))collect('maintenance');});});
 const doctrinePage=document.getElementById('doctrine');doctrinePage?.querySelectorAll('p').forEach(el=>{if(el.innerText.includes('TERMINOLOGY WARNING')){el.classList.add('evidence-target');el.addEventListener('click',()=>collect('doctrine'));}});
 document.querySelectorAll('#puzzle1 .doc').forEach(el=>{el.classList.add('evidence-target');el.addEventListener('click',()=>collect('obituaries'));});
 const incidentPage=document.getElementById('incidents');incidentPage?.querySelectorAll('.notice').forEach(el=>{el.classList.add('evidence-target');el.addEventListener('click',()=>collect('addendum'));});
 // Awareness rises for wrong conclusions, failed searches and attempted access before authorization.
 const originalSolve=window.solve;
 document.querySelectorAll('[id^=feedback]').forEach(fb=>{const observer=new MutationObserver(()=>{if(fb.textContent.toLowerCase().includes('not accepted'))raise('incorrect conclusion');});observer.observe(fb,{childList:true,characterData:true,subtree:true});});
 document.getElementById('searchBtn')?.addEventListener('click',()=>{setTimeout(()=>{const q=document.getElementById('archiveSearch').value.trim();if(q.length>=3&&document.getElementById('searchStatus').textContent.includes('0 MATCHING'))raise('empty search');if(state.awareness>=5){const docs=[...document.querySelectorAll('#archiveResults .doc')];docs.reverse().forEach(el=>el.parentNode.appendChild(el));}},0);});
 document.querySelectorAll('[data-page="restricted"],[data-page="terminal"]').forEach(btn=>btn.addEventListener('click',()=>{if(progress.solved.length<4)raise('restricted access attempt');}));
 // Three quiet-reading locations let the player lower awareness once each; this is earned, not a reset button.
 ['doctrine','maintenance','testimonies'].forEach(id=>{document.querySelector(`[data-page="${id}"]`)?.addEventListener('click',()=>{if(state.awareness>0&&!state.recovery[id]){state.recovery[id]=true;state.awareness=Math.max(0,state.awareness-1);persist();}});});
 // Terminal becomes less reliable at high awareness, but never destroys progress or blocks commands permanently.
 const term=document.getElementById('terminalInput');term?.addEventListener('keydown',e=>{if(e.key==='Enter'&&state.awareness>=7){const v=term.value.trim().toLowerCase();if(v==='status'||v==='help'){setTimeout(()=>{const out=document.getElementById('terminalOutput');if(out)out.textContent+='\
[ARCHIVE INTERFERENCE] Command history may be incomplete. Consult the original records.';},30);}}});
 render();window.ArchiveDossier=Object.freeze({status:()=>({evidence:state.evidence.length+'/10',awareness:state.awareness+'/8',session:'018'}),inspect:()=>{panel.classList.add('open');panel.setAttribute('aria-hidden','false');toggle.setAttribute('aria-expanded','true');}});
 console.info('%c[FIELD DOSSIER AVAILABLE]','color:#b58b78;font-weight:bold');console.info('The archive does not reward guessing. Examine the records, then compare what they say.');console.info('Open FIELD DOSSIER at the lower-right corner, or press D.');
